module max_profit (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    \n    // Configuration for 4 snack positions\n    input wire [3:0] f0, f1, f2, f3,\n    input wire [7:0] p0, p1, p2, p3,\n    input wire [7:0] m0, m1, m2, m3,\n    input wire [3:0] s0, s1, s2, s3,\n    \n    output reg [15:0] profit,\n    output reg done\n);\n    \n    // State definitions\n    localparam [1:0] IDLE     = 2'd0;\n    localparam [1:0] COMPUTE  = 2'd1;\n    localparam [1:0] UPDATE   = 2'd2;\n    localparam [1:0] FINISHED = 2'd3;\n    reg [1:0] state;\n    \n    // Current transaction counts\n    reg [3:0] x0, x1, x2, x3;\n    \n    // Profit calculations\n    reg [15:0] max_profit;\n    reg [15:0] current_profit;\n    reg valid_combo;\n    \n    // Convert f(i) to 0-based index\n    wire [3:0] f_val [0:3];\n    assign f_val[0] = f0 - 4'd1;\n    assign f_val[1] = f1 - 4'd1;\n    assign f_val[2] = f2 - 4'd1;\n    assign f_val[3] = f3 - 4'd1;\n    \n    // Profit per transaction (signed)\n    wire signed [15:0] profit_per [0:3];\n    assign profit_per[0] = (f_val[0] == 3'd1) ? (m1 - p0) : \n                          (f_val[0] == 3'd2) ? (m2 - p0) : \n                          (f_val[0] == 3'd3) ? (m3 - p0) : \n                          (m0 - p0);\n    \n    assign profit_per[1] = (f_val[1] == 3'd1) ? (m1 - p1) : \n                          (f_val[1] == 3'd2) ? (m2 - p1) : \n                          (f_val[1] == 3'd3) ? (m3 - p1) : \n                          (m0 - p1);\n    \n    assign profit_per[2] = (f_val[2] == 3'd1) ? (m1 - p2) : \n                          (f_val[2] == 3'd2) ? (m2 - p2) : \n                          (f_val[2] == 3'd3) ? (m3 - p2) : \n                          (m0 - p2);\n    \n    assign profit_per[3] = (f_val[3] == 3'd1) ? (m1 - p3) : \n                          (f_val[3] == 3'd2) ? (m2 - p3) : \n                          (f_val[3] == 3'd3) ? (m3 - p3) : \n                          (m0 - p3);\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state       <= IDLE;\n            profit      <= 16'd0;\n            done        <= 1'b0;\n            x0          <= 4'd0;\n            x1          <= 4'd0;\n            x2          <= 4'd0;\n            x3          <= 4'd0;\n            max_profit  <= 16'd0;\n            current_profit <= 16'd0;\n            valid_combo <= 1'b0;\n        end\n        else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        x0 <= 4'd0;\n                        x1 <= 4'd0;\n                        x2 <= 4'd0;\n                        x3 <= 4'd0;\n                        max_profit <= 16'd0;\n                    end\n                end\n                \n                COMPUTE: begin\n                    // Check constraints\n                    valid_combo <= 1'b1;\n                    \n                    if (x0 + ((f_val[1]==0) ? x1 : 4'd0) + \n                             ((f_val[2]==0) ? x2 : 4'd0) + \n                             ((f_val[3]==0) ? x3 : 4'd0) > s0) begin\n                        valid_combo <= 1'b0;\n                    end\n                    if (x1 + ((f_val[0]==1) ? x0 : 4'd0) + \n                             ((f_val[2]==1) ? x2 : 4'd0) + \n                             ((f_val[3]==1) ? x3 : 4'd0) > s1) begin\n                        valid_combo <= 1'b0;\n                    end\n                    if (x2 + ((f_val[0]==2) ? x0 : 4'd0) + \n                             ((f_val[1]==2) ? x1 : 4'd0) + \n                             ((f_val[3]==2) ? x3 : 4'd0) > s2) begin\n                        valid_combo <= 1'b0;\n                    end\n                    if (x3 + ((f_val[0]==3) ? x0 : 4'd0) + \n                             ((f_val[1]==3) ? x1 : 4'd0) + \n                             ((f_val[2]==3) ? x2 : 4'd0) > s3) begin\n                        valid_combo <= 1'b0;\n                    end\n                    \n                    // Calculate current profit\n                    current_profit <= (x0 * profit_per[0]) + \n                                     (x1 * profit_per[1]) + \n                                     (x2 * profit_per[2]) + \n                                     (x3 * profit_per[3]);\n                    state <= UPDATE;\n                end\n                \n                UPDATE: begin\n                    if (valid_combo && (current_profit > max_profit)) begin\n                        max_profit <= current_profit;\n                    end\n                    \n                    // Increment counters (nested loop style)\n                    if (x3 < s3) begin\n                        x3 <= x3 + 4'd1;\n                    end\n                    else begin\n                        x3 <= 4'd0;\n                        if (x2 < s2) begin\n                            x2 <= x2 + 4'd1;\n                        end\n                        else begin\n                            x2 <= 4'd0;\n                            if (x1 < s1) begin\n                                x1 <= x1 + 4'd1;\n                            end\n                            else begin\n                                x1 <= 4'd0;\n                                if (x0 < s0) begin\n                                    x0 <= x0 + 4'd1;\n                                end\n                                else begin\n                                    state <= FINISHED;\n                                    profit <= max_profit;\n                                end\n                            end\n                        end\n                    end\n                    \n                    if (state != FINISHED) begin\n                        state <= COMPUTE;\n                    end\n                end\n                \n                FINISHED: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule